const products=[]; let expected=null;
for(const item of $input.all()){
 const html=String(item.json.data||'');
 const m=html.match(/<script data-page="app" type="application\/json">([\s\S]*?)<\/script>/);
 if(!m) throw new Error('Website catalogue format changed; do not quote cached prices.');
 const page=JSON.parse(m[1]);
 if(page.props?.storeSettings?.currency!=='UGX') throw new Error('Website currency changed; review catalogue formatting.');
 const list=page.props.products;
 if(!Array.isArray(list?.data)) throw new Error('Website product list missing.');
 expected=list.total;
 for(const p of list.data)if(p.is_active && !products.some(x=>x.id===p.id))products.push(p);
}
if(expected!==products.length)throw new Error('Incomplete website catalogue: '+products.length+' of '+expected);
const grouped=new Map();
for(const p of products){
 const category=({ 'hair-care':'Hair','body-care':'Body','baby-care':'Baby','fragrance':'Fragrance'})[p.category?.slug]||p.category?.name||'Other';
 const key=category+'|'+p.name; if(!grouped.has(key))grouped.set(key,{name:p.name,category,variants:[]});
 const size=p.size||(String(p.subtitle||'').match(/\b\d+(?:\.\d+)?\s*(?:ml|g|kg|l|oz)\b/i)||[])[0]||null;
 grouped.get(key).variants.push({product_id:p.id,slug:p.slug,size,colors:p.color?String(p.color).split(',').map(x=>x.trim()):[],retail_price_ugx:Number(p.price),stock_status:Number(p.stock)>0?'In stock':'Out of stock',wholesale_price_ugx:p.wholesale_price==null?null:Number(p.wholesale_price),wholesale_min_qty:p.wholesale_min_qty==null?null:Number(p.wholesale_min_qty)});
}
const structured=[...grouped.values()];
const catalog_text=structured.map(p=>p.name+'\nCategory: '+p.category+'\nVariants:\n'+p.variants.map(v=>'• '+(v.size?v.size+' — ':'')+'UGX '+v.retail_price_ugx+' — '+v.stock_status+(v.wholesale_price_ugx!=null&&v.wholesale_min_qty>0?' | Wholesale: UGX '+v.wholesale_price_ugx+' each from '+v.wholesale_min_qty+' units':'')).join('\n')).join('\n\n');
return [{json:{catalog_text,products:structured,catalog_source:'https://ellenacosms.com/shop',catalog_retrieved_at:new Date().toISOString(),website_product_count:products.length}}];
